-- insert-cordoba-centers.sql
-- Inserta los 129 centros de educacion infantil de primer ciclo (0-3 anos)
-- del termino municipal de Cordoba capital investigados y humanizados en este sprint.
-- Fuente primaria: "Centros de primer ciclo de educacion infantil en Andalucia, con
-- alumnado matriculado" (Junta de Andalucia, Consejeria de Desarrollo Educativo y
-- Formacion Profesional, portal de datos abiertos), filtrado por D_MUNICIPIO='Córdoba'.
-- Complementado con: (a) el Portal de Escolarizacion 0-3 anos de la Junta de Andalucia
-- (horario homogeneo de la red publica autonomica), (b) la web institucional de la
-- Entidad Local Autonoma de Encinarejo, (c) la pagina de centros de educacion infantil
-- del Ejercito de Tierra / DIAPER (Ministerio de Defensa) para el centro de Cerro
-- Muriano, y (d) webs oficiales propias de un subconjunto de centros privados para
-- confirmar servicios concretos. Ver docs/data-sources-cordoba.md y
-- data/enrichment/cordoba-centers.json.
--
-- Ambito: unicamente el termino municipal de Cordoba capital (D_MUNICIPIO='Córdoba' en
-- la fuente oficial, valor exacto). Se excluyen explicitamente los otros ~74 municipios
-- de la provincia de Cordoba (Lucena, Palma del Rio, Puente Genil, Baena, Montilla,
-- Cabra, Priego de Cordoba, Pozoblanco, Villanueva de Cordoba, Villafranca de Cordoba,
-- Villaviciosa de Cordoba, Montalban de Cordoba, etc.) aunque compartan parte del nombre
-- o aparecieran en la misma fuente provincial.
--
-- Ownership: 'publico' se ha usado para (a) las 11 escuelas infantiles de la red
-- genuina de titularidad de la Junta de Andalucia (confirmadas por email institucional
-- @juntadeandalucia.es en la fuente oficial: Virgen del Carmen, Azahara, Parque
-- Figueroa, Jesus Ledesma, Nuestra Senora de la Soledad, La Victoria, Los Reyes, Peter
-- Pan, San Jose, San Rafael, Santuario), (b) Ciguena Blanca, escuela infantil de la
-- Entidad Local Autonoma de Encinarejo (nucleo de poblacion con competencias propias
-- dentro del termino municipal de Cordoba desde 1957), y (c) Cerro Muriano, escuela
-- infantil de titularidad del Ministerio de Defensa dentro de la Base Militar de Cerro
-- Muriano, con gestion operativa delegada en una empresa de servicios educativos.
-- Los 116 centros privados adheridos o no al Programa de Ayuda a las Familias de la
-- Junta de Andalucia llevan ownership='privado', nunca 'concertado': Andalucia no
-- tiene concierto educativo formal para el primer ciclo de infantil (0-3 anos),
-- siguiendo el mismo criterio ya validado en la correccion post-auditoria de Sevilla
-- y aplicado desde el origen en Malaga (2026-07-12). Ver docs/cordoba-quality-report.md,
-- seccion 1.
--
-- Todos los centros entran con status='draft' (no visibles publicamente por RLS hasta
-- cambiarlos a 'published' manualmente tras auditoria, igual que en Madrid, Barcelona,
-- Valencia, Zaragoza, Murcia, Sevilla, Palma, Malaga y Alicante).
-- No toca ningun centro de Madrid, Barcelona, Valencia, Zaragoza, Murcia, Sevilla,
-- Palma, Malaga ni Alicante.
-- No borra ni modifica filas existentes (upsert por slug: si un slug ya existe se
-- actualiza, no se duplica).
-- Generado: 2026-07-12. Revisar antes de ejecutar.
-- Sin DELETE / DROP / TRUNCATE.

BEGIN;

-- Aseguramos que la ciudad "cordoba" existe antes de insertar sus centros.
INSERT INTO cities (slug, name, province, region)
VALUES ('cordoba', 'Córdoba', 'Córdoba', 'Andalucía')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO centers (
  slug, name, type, ownership, street, postal_code, city_slug, city_name, neighborhood, district, neighborhood_barrio, latitude, longitude, phone, email, website, age_min_months, age_max_months, schedule, services, short_description, long_description, images, faqs, is_claimed, is_verified, social_links, pedagogical_approach, source_url, source_urls_secondary, verified_at, verification_status, confidence_level, data_conflicts, status
)
VALUES
('el-tablerillo-cordoba', 'El Tablerillo', 'guarderia', 'privado', 'Ctra. de Las Ermitas, 48', '14012', 'cordoba', 'Córdoba', NULL, NULL, NULL, 37.899605628, -4.792927242, '957272001', 'tablerillo@escuelainfantileltablerillo.com', NULL, 4, 36, NULL, '{}'::text[], 'Centro de educación infantil de primer ciclo situado en Ctra. de Las Ermitas, 48, 14012, Córdoba: El Tablerillo, no adherido al Programa de Ayuda a las Familias de la Junta de Andalucía. No consta información oficial adicional sobre servicios concretos en el momento de esta consulta.', NULL, '{}'::text[], '[{"question":"¿Dónde está ubicado El Tablerillo?","answer":"El centro se encuentra en Ctra. de Las Ermitas, 48, 14012, en Córdoba."},{"question":"¿Qué edades atiende este centro?","answer":"Es un centro de educación infantil de primer ciclo, dirigido a niños de 0 a 3 años."},{"question":"¿Es un centro público o privado?","answer":"Es un centro de titularidad privada. Según el registro de centros de primer ciclo de educación infantil de la Junta de Andalucía, no figura adherido al Programa de Ayuda a las Familias de la Junta de Andalucía en el registro consultado."},{"question":"¿Cómo puedo contactar con el centro?","answer":"Puedes llamar al teléfono 957272001, escribir a tablerillo@escuelainfantileltablerillo.com."},{"question":"¿Está verificada la información de esta ficha?","answer":"Los datos básicos proceden del registro oficial de centros de primer ciclo de educación infantil de la Junta de Andalucía (Consejería de Desarrollo Educativo y Formación Profesional). Si representas este centro, puedes solicitar una actualización o reclamar la ficha."}]'::jsonb, false, false, '{}'::jsonb, '{}'::text[], 'https://www.juntadeandalucia.es/datosabiertos/portal/dataset/centros-de-primer-ciclo-de-educacion-infantil-en-andalucia', '{}'::text[], '2026-07-12'::date, 'unverified', 'medium', '{}'::jsonb, 'draft'),
('betica-mudarra-cordoba', 'Bética-Mudarra', 'guarderia', 'privado', 'C/ Vandalino, 6', '14012', 'cordoba', 'Córdoba', NULL, NULL, NULL, 37.91207303005724, -4.794759750366211, '957275600', 'beticas@telefonica.net', 'https://betica-mudarra.org/cei/', 4, 36, 'Aula matinal de 7:30 a 9:00 horas (según su web oficial, a nivel de centro).', ARRAY['comedor','cocina-propia','servicio-madrugadores','patio-exterior']::text[], 'Situado en C/ Vandalino, 6, 14012, Córdoba, Bética-Mudarra confirma en su web oficial los siguientes servicios para el primer ciclo de educación infantil: comedor, cocina propia, servicio de madrugadores/aula matinal, patio exterior.', 'Bética-Mudarra es un centro privado de educación infantil de primer ciclo (0-3 años), con sede en C/ Vandalino, 6, 14012, Córdoba.

Según el registro oficial de la Junta de Andalucía, no figura adherido al Programa de Ayuda a las Familias en el momento de esta consulta.

Es el Centro de Educación Infantil (CEI) de primer ciclo del Colegio Bética-Mudarra, un centro educativo más amplio (infantil, primaria, secundaria y bachillerato). Su web oficial confirma comida elaborada en cocina propia del centro, aula matinal de 7:30 a 9:00 horas y una zona de recreo al aire libre para las aulas de 0-1 y 2 años.

Para conocer el proyecto educativo completo, precios, plazas disponibles y proceso de admisión, se recomienda contactar directamente con el centro.', '{}'::text[], '[{"question":"¿Dónde está ubicado Bética-Mudarra?","answer":"El centro se encuentra en C/ Vandalino, 6, 14012, en Córdoba."},{"question":"¿Qué edades atiende este centro?","answer":"Es un centro de educación infantil de primer ciclo, dirigido a niños de 0 a 3 años."},{"question":"¿Es un centro público o privado?","answer":"Es un centro de titularidad privada. Según el registro de centros de primer ciclo de educación infantil de la Junta de Andalucía, no figura adherido al Programa de Ayuda a las Familias de la Junta de Andalucía en el registro consultado."},{"question":"¿Tiene servicio de comedor?","answer":"Sí, según fuente verificada el centro ofrece servicio de comedor, con cocina propia."},{"question":"¿Tiene horario ampliado o servicio de madrugadores?","answer":"Sí, según fuente verificada el centro ofrece aula matinal/madrugadores."},{"question":"¿Tiene patio exterior?","answer":"Sí, según su web oficial el centro dispone de patio o zona exterior propia."},{"question":"¿Cómo puedo contactar con el centro?","answer":"Puedes llamar al teléfono 957275600, escribir a beticas@telefonica.net, consultar su web oficial (https://betica-mudarra.org/cei/)."}]'::jsonb, false, false, '{}'::jsonb, '{}'::text[], 'https://www.juntadeandalucia.es/datosabiertos/portal/dataset/centros-de-primer-ciclo-de-educacion-infantil-en-andalucia', ARRAY['https://betica-mudarra.org/servicios/','https://betica-mudarra.org/cei/']::text[], '2026-07-12'::date, 'unverified', 'high', '{}'::jsonb, 'draft'),
('la-salle-cordoba', 'La Salle', 'guarderia', 'privado', 'C/ San Juan Bautista de la Salle, 7', '14012', 'cordoba', 'Córdoba', NULL, NULL, NULL, 37.91030391472861, -4.800606966018677, '957275700', 'secretaria@lasallecordoba.es', 'https://lasallecordoba.es/escuela-infantil-la-salle-0-3-anos/', 4, 36, NULL, ARRAY['comedor','servicio-madrugadores','orientacion-pedagogica']::text[], 'Con sede en C/ San Juan Bautista de la Salle, 7, 14012, Córdoba, La Salle es un centro privado de primer ciclo de educación infantil que confirma en su web oficial servicios como comedor, servicio de madrugadores/aula matinal, orientación pedagógica.', 'La Salle es un centro privado de educación infantil de primer ciclo (0-3 años), con sede en C/ San Juan Bautista de la Salle, 7, 14012, Córdoba.

Según el registro oficial de la Junta de Andalucía, no figura adherido al Programa de Ayuda a las Familias en el momento de esta consulta.

Su web oficial confirma comedor escolar, aula matinal y un gabinete/servicio de orientación para el primer ciclo de educación infantil (0-3 años), integrado en el Colegio La Salle Córdoba, en funcionamiento desde septiembre de 2022.

Para conocer el proyecto educativo completo, precios, plazas disponibles y proceso de admisión, se recomienda contactar directamente con el centro.', '{}'::text[], '[{"question":"¿Dónde está ubicado La Salle?","answer":"El centro se encuentra en C/ San Juan Bautista de la Salle, 7, 14012, en Córdoba."},{"question":"¿Qué edades atiende este centro?","answer":"Es un centro de educación infantil de primer ciclo, dirigido a niños de 0 a 3 años."},{"question":"¿Es un centro público o privado?","answer":"Es un centro de titularidad privada. Según el registro de centros de primer ciclo de educación infantil de la Junta de Andalucía, no figura adherido al Programa de Ayuda a las Familias de la Junta de Andalucía en el registro consultado."},{"question":"¿Tiene servicio de comedor?","answer":"Sí, según fuente verificada el centro ofrece servicio de comedor."},{"question":"¿Tiene horario ampliado o servicio de madrugadores?","answer":"Sí, según fuente verificada el centro ofrece aula matinal/madrugadores."},{"question":"¿Ofrece orientación pedagógica a las familias?","answer":"Sí, según fuente verificada el centro cuenta con un servicio de orientación pedagógica."},{"question":"¿Cómo puedo contactar con el centro?","answer":"Puedes llamar al teléfono 957275700, escribir a secretaria@lasallecordoba.es, consultar su web oficial (https://lasallecordoba.es/escuela-infantil-la-salle-0-3-anos/)."}]'::jsonb, false, false, '{}'::jsonb, '{}'::text[], 'https://www.juntadeandalucia.es/datosabiertos/portal/dataset/centros-de-primer-ciclo-de-educacion-infantil-en-andalucia', ARRAY['https://lasallecordoba.es/escuela-infantil-la-salle-0-3-anos/']::text[], '2026-07-12'::date, 'unverified', 'high', '{}'::jsonb, 'draft'),
